<div class="container-fluid py-3"><div class="d-flex justify-content-between align-items-center mb-3"><div><span class="badge bg-danger">LIVE WEBINAR</span><h4 class="d-inline ms-2">{{ $webinar->title }}</h4></div><a href="{{ route('webinars.show',$webinar) }}" class="btn btn-outline-secondary">Leave</a></div><div id="video-grid" class="rounded-4 bg-dark p-2" style="min-height:70vh;display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:10px"></div><div class="text-center mt-3"><button id="mic" class="btn btn-light rounded-pill px-4">Mute</button> <button id="camera" class="btn btn-light rounded-pill px-4">Camera off</button></div><div id="agora-error" class="alert alert-warning mt-3 d-none"></div></div>
<script src="https://download.agora.io/sdk/release/AgoraRTC_N.js"></script><script>
const appId=@json($agoraAppId), channel=@json($webinar->agora_channel), token=@json($agoraToken ?: null);let client,tracks=[];
async function start(){if(!appId){throw new Error('Agora is not configured. Set AGORA_APP_ID and a valid AGORA_TEMPORARY_TOKEN in .env.');}client=AgoraRTC.createClient({mode:'rtc',codec:'vp8'});client.on('user-published',async(user,type)=>{await client.subscribe(user,type);if(type==='video'){const el=document.createElement('div');el.id='u-'+user.uid;el.style.minHeight='320px';document.getElementById('video-grid').appendChild(el);user.videoTrack.play(el);}if(type==='audio')user.audioTrack.play();});client.on('user-unpublished',user=>document.getElementById('u-'+user.uid)?.remove());await client.join(appId,channel,token,null);tracks=await AgoraRTC.createMicrophoneAndCameraTracks();const mine=document.createElement('div');mine.style.minHeight='320px';document.getElementById('video-grid').appendChild(mine);tracks[1].play(mine);await client.publish(tracks);}
start().catch(e=>{const box=document.getElementById('agora-error');box.textContent=e.message;box.classList.remove('d-none')});document.getElementById('mic').onclick=async function(){const muted=!tracks[0].muted;await tracks[0].setMuted(muted);this.textContent=muted?'Unmute':'Mute'};document.getElementById('camera').onclick=async function(){const muted=!tracks[1].muted;await tracks[1].setMuted(muted);this.textContent=muted?'Camera on':'Camera off'};
</script>
